package config

// Setting documents one setting for the configuration reference.
type Setting struct {
	// Key is the variable name; amp.yaml nests it by "_" (DB_HOST is db: {host}).
	Key         string
	Group       string
	Default     string
	Description string
	Secret      bool
}

// Groups orders the reference's sections.
var Groups = []string{
	"Public URLs",
	"Server and ports",
	"Database",
	"Sign-in and tokens",
	"Identity provider (ThunderID)",
	"Secrets and state",
	"Events",
	"Audit",
	"Console",
	"amp init",
	"Operations",
}

